const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the point geometry
  const point = ee.Geometry.Point([-122.403124, 40.575441]);

  // Define date range for August 25, 2020
  const startDate = '2020-08-25';
  const endDate = '2020-08-26';

  // Load MERRA-2 aerosol data
  const collection = ee.ImageCollection('NASA/GSFC/MERRA/2/M2T1NXAER')
    .filterDate(startDate, endDate)
    .filterBounds(point);

  // Check if collection is empty
  const collectionSize = collection.size().getInfo();
  console.log(`MERRA-2 images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the first image (should be only one for daily data)
  const image = collection.first();

  // Calculate total black carbon (BCPHILIC + BCPHOBIC) in kg/m²
  const totalBC_kg = image.select('BCPHILIC').add(image.select('BCPHOBIC'));

  // Convert to mg/m² (1 kg/m² = 1,000,000 mg/m²)
  const totalBC_mg = totalBC_kg.multiply(1000000);

  // Extract value at the point
  const bcValue = totalBC_mg.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: point,
    scale: 50000,  // MERRA-2 native resolution is ~50km
    maxPixels: 1e9
  }).get('BCPHILIC');  // Using BCPHILIC as the band name for the result

  const bcValueInfo = bcValue.getInfo();
  console.log(`Black Carbon Concentration: ${bcValueInfo} mg/m²`);

  // Check if value is valid
  if (bcValueInfo === null || bcValueInfo === undefined || isNaN(bcValueInfo)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if concentration is greater than 12 mg/m²
  if (bcValueInfo > 12) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
